// Get availability data from Google Sheets (previous node)
  const availabilityData = $input.all().map(item => item.json);

  // Get search parameters - passed through the flow
  // We need to get these from a node that's actually in our execution path
  const switchByStageOutput = $('Switch by Stage').first().json;
  const searchKeyType = switchByStageOutput.search_key_type;
  const keyTypeValue = switchByStageOutput.key_type_value;

  // Get date context - need to trace back through the flow
  const datePreprocessor = $('Date_preprocessor').first().json;
  const currentDay = datePreprocessor.current_day;
  const tomorrowDay = datePreprocessor.tomorrow_day;
  const currentDateReadable = datePreprocessor.current_date_readable;

  // Day columns mapping (matching your sheet headers)
  const dayColumns = ['Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];

  let result = {
    search_key_type: searchKeyType,
    key_type_value: keyTypeValue,
    current_day: currentDay,
    current_date_readable: currentDateReadable,
    is_today: false,
    is_tomorrow: false,
    disponibles: [],
    dias_disponibles: [],
    found: false
  };

  if (searchKeyType === 'dia') {
    // Search by day: find all masajistas available on that day
    const searchDay = keyTypeValue;

    result.is_today = (searchDay === currentDay);
    result.is_tomorrow = (searchDay === tomorrowDay);

    for (const row of availabilityData) {
      const masajista = row.Masajista;
      const isAvailable = row[searchDay];

      if (isAvailable && isAvailable.toUpperCase() === 'SI') {
        result.disponibles.push(masajista);
      }
    }

    result.found = result.disponibles.length > 0;

  } else if (searchKeyType === 'masajista') {
    // Search by masajista: find all days they work
    const searchMasajista = keyTypeValue;

    const masajistaRow = availabilityData.find(
      row => row.Masajista && row.Masajista.toLowerCase() === searchMasajista.toLowerCase()
    );

    if (masajistaRow) {
      for (const day of dayColumns) {
        if (masajistaRow[day] && masajistaRow[day].toUpperCase() === 'SI') {
          result.dias_disponibles.push(day);
        }
      }
      result.found = result.dias_disponibles.length > 0;
    }
  }

  return {
    ...result,
    phone_number: datePreprocessor.phone_number
  };

